/* Browser-local editor; exported stories require only HTML and CSS. */
const $=id=>document.getElementById(id), editor=$('workskin');
let graphView=false, graphNodes=new Map(), graphSelection=null, graphZoom=0.8, graphBounds={width:1,height:1};
let css='', savedRange=null, history=[], cursor=-1, timer, originalView=false;
const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paragraphs=t=>t.split(/\n\s*\n/).filter(x=>x.trim()).map(x=>'<p>'+esc(x).replace(/\n/g,'<br>')+'</p>').join('');
const slot=h=>`<div data-editable="true" contenteditable="true">${h||'<p><br></p>'}</div>`;
const wrap=(cls,h)=>`<div class="widget ${cls}" contenteditable="false" data-widget="${cls}">${h}</div>`;
function notice(s){$('status').textContent=s;}
const DRAFT_KEY='paper-studio-document-v3', BACKUP_KEY='paper-studio-backup-v3';
let lastBackupAt=0;
let draftDatabase,indexedReadFailed=false;
function openDraftDatabase(){if(!draftDatabase)draftDatabase=new Promise((resolve,reject)=>{const request=indexedDB.open('paper-studio-drafts',1);request.onupgradeneeded=()=>request.result.createObjectStore('documents');const timeout=setTimeout(()=>reject(Error('浏览器数据库不可用')),2000);request.onsuccess=()=>{clearTimeout(timeout);resolve(request.result);};request.onblocked=()=>{clearTimeout(timeout);reject(Error('数据库被阻止'));};request.onerror=()=>{clearTimeout(timeout);reject(request.error);};});return draftDatabase;}
async function indexedDraft(mode,record){const database=await openDraftDatabase();return new Promise((resolve,reject)=>{let finished=false;const transaction=database.transaction('documents',mode==='get'?'readonly':'readwrite'),store=transaction.objectStore('documents');const request=mode==='get'?store.get(DRAFT_KEY):store.put(record,DRAFT_KEY);const timer=setTimeout(()=>{if(finished)return;finished=true;try{transaction.abort();}catch{}reject(Error('浏览器存储读取超时'));},2000);transaction.oncomplete=()=>{if(finished)return;finished=true;clearTimeout(timer);resolve(request.result);};const fail=()=>{if(finished)return;finished=true;clearTimeout(timer);reject(transaction.error||Error('浏览器存储不可用'));};transaction.onerror=fail;transaction.onabort=fail;});}

async function readIndexedDraft(){try{const value=await indexedDraft('get');indexedReadFailed=false;return value?parseDocument(JSON.stringify(value)):null;}catch{indexedReadFailed=true;return null;}}
function backupToIndexed(record){if(indexedReadFailed){$('saveState').textContent='浏览器存储不可用';$('saveState').dataset.state='error';return;}indexedDraft('put',record).then(()=>{$('saveState').textContent='已自动保存';$('saveState').dataset.state='saved';$('saveState').title='已保存到本机浏览器数据库';}).catch(()=>{$('saveState').textContent='浏览器禁止自动保存';$('saveState').dataset.state='error';$('saveState').title='请保存或复制草稿；用完整浏览器打开文件后再试';});}
function documentRecord(){syncChapter();return {book:JSON.parse(JSON.stringify(book)),format:'paper-studio',version:1,editorVersion:3,savedAt:new Date().toISOString(),html:editor.innerHTML,assets:referencedMusicAssets(),settings:{storyFull:$('storyFull').checked,noCSS:$('noCSS').checked,storyTheme:$('storyTheme')?.value||'gray'}};}
function parseDocument(text){const doc=JSON.parse(text);if(!doc||doc.format!=='paper-studio'||doc.version!==1||typeof doc.html!=='string')throw Error('不是纸间的正文保存文件');const settings=doc.settings||{};return {...doc,settings:{sender:typeof settings.sender==='string'?settings.sender:'',recipient:typeof settings.recipient==='string'?settings.recipient:'',storyFull:typeof settings.storyFull==='boolean'?settings.storyFull:true,noCSS:typeof settings.noCSS==='boolean'?settings.noCSS:true,storyTheme:['black','white','gray'].includes(settings.storyTheme)?settings.storyTheme:'gray'}};}
function readStored(key){try{const data=localStorage.getItem(key);return data?parseDocument(data):null;}catch{return null;}}
function persist(){const record=documentRecord();let prior=null;try{prior=localStorage.getItem(DRAFT_KEY);}catch{}$('count').textContent=editorText(editor).replace(/\s/g,'').length+' 字';try{localStorage.setItem(DRAFT_KEY,JSON.stringify(record));$('saveState').textContent='已自动保存';$('saveState').dataset.state='saved';$('saveState').title='自动保存于 '+new Date(record.savedAt).toLocaleTimeString();}catch{backupToIndexed(record);$('saveState').textContent='正在尝试备用保存';$('saveState').dataset.state='error';$('saveState').title='请点击「保存到本地」，把正文下载为文件。';return false;}if(prior&&Date.now()-lastBackupAt>30000){try{parseDocument(prior);localStorage.setItem(BACKUP_KEY,prior);lastBackupAt=Date.now();}catch{/* Current draft remains saved if the optional backup fails. */}}return true;}
function preserveBackup(){try{localStorage.setItem(BACKUP_KEY,JSON.stringify(documentRecord()));lastBackupAt=Date.now();}catch{/* A local document file can still be saved without browser storage. */}}
function sanitizeDocument(markup){const template=document.createElement('template');template.innerHTML=markup;const allowed=new Set(['P','DIV','SPAN','LABEL','BR','B','STRONG','EM','I','U','S','MARK','DETAILS','SUMMARY','BLOCKQUOTE','PRE','CODE','HR','BUTTON','DFN']);const discard=new Set(['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','LINK','META','BASE','SVG','MATH','TEMPLATE']);for(const el of [...template.content.querySelectorAll('*')]){if(discard.has(el.tagName)){el.remove();continue;}if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);continue;}for(const attr of [...el.attributes])if(!['class','data-editable','data-widget','data-field','data-placeholder','data-action','data-ending','data-node-id','data-next-id','data-board-x','data-board-y','tabindex','aria-label','aria-hidden'].includes(attr.name))el.removeAttribute(attr.name);}return template.innerHTML;}
function applySettings(settings){$('storyFull').checked=settings.storyFull;$('noCSS').checked=settings.noCSS;$('storyTheme').value=settings.storyTheme||'gray';}
function loadDocument(record){activeFontArt=null;fontRange=null;pendingConnection=null;selectedConnection=null;const migrated=migrateEditor(sanitizeDocument(record.html));preserveBackup();showView('edit');restoreMusicAssets(record.assets);editor.innerHTML=migrated.html;applySettings({...record.settings,storyFull:record.editorVersion>=2?record.settings.storyFull:migrated.interactive});initBook(record);history=[];cursor=-1;setEditable();savedRange=null;$('outputPanel').hidden=true;checkpoint();persist();showView('graph');notice('作品、章节和加工效果已恢复。');}
function checkpoint(){const state={html:editor.innerHTML,storyFull:$('storyFull').checked,noCSS:$('noCSS').checked,storyTheme:$('storyTheme')?.value||'gray'};if(history[cursor]&&JSON.stringify(history[cursor])===JSON.stringify(state))return;history=history.slice(0,cursor+1);history.push(state);if(history.length>80)history.shift();cursor=history.length-1;persist();}
function restore(){const state=history[cursor];editor.innerHTML=state.html;$('storyFull').checked=state.storyFull;$('noCSS').checked=state.noCSS;$('storyTheme').value=state.storyTheme||'gray';savedRange=null;setEditable();if(originalView)$('rawDocument').textContent=editorText(editor);if(graphView)renderGraph();persist();}
function setEditable(){editor.querySelectorAll('details.stack-spoiler').forEach(el=>el.open=true);editor.contentEditable='true';editor.querySelectorAll('[data-widget]').forEach(x=>x.contentEditable='false');editor.querySelectorAll('[data-editable]').forEach(x=>x.contentEditable='true');}
document.addEventListener('selectionchange',()=>{const s=getSelection();if(s.rangeCount&&!s.isCollapsed&&editor.contains(s.anchorNode)&&editor.contains(s.focusNode))savedRange=s.getRangeAt(0).cloneRange();});
document.querySelectorAll('[data-effect]').forEach(b=>b.addEventListener('mousedown',e=>e.preventDefault()));
function getRange(){if(!savedRange||!editor.contains(savedRange.commonAncestorContainer)||savedRange.collapsed){notice('请先在正文中选中要加工的文字。');return null;}const r=savedRange.cloneRange();const field=(r.startContainer.nodeType===1?r.startContainer:r.startContainer.parentElement).closest('[data-field]');if(field&&['sender','recipient','option-title','branch-prompt','audio-url','track-title','track-artist','cover-url'].includes(field.dataset.field)){notice('姓名和选项标题直接编辑文字即可。');return null;}const parent=n=>n.nodeType===1?n:n.parentElement;const startSlot=parent(r.startContainer).closest('[data-editable]'),endSlot=parent(r.endContainer).closest('[data-editable]');for(const widget of editor.querySelectorAll('[data-widget]')){if(!r.intersectsNode(widget))continue;if(startSlot&&startSlot===endSlot&&widget.contains(startSlot))continue;const bounds=document.createRange();bounds.selectNode(widget);if(r.compareBoundaryPoints(Range.START_TO_START,bounds)>0||r.compareBoundaryPoints(Range.END_TO_END,bounds)<0){notice('跨越效果时，请完整选中该效果；也可以只选中效果内的正文。');return null;}}return r;}
function rangeHTML(r){const div=document.createElement('div');div.append(r.cloneContents());return div.innerHTML;}
function plainHTML(h){const d=document.createElement('div');d.innerHTML=h;d.querySelectorAll('[aria-hidden=true],.stack-spoiler>summary,button,.printer-header,.printer-trigger>summary,.printer-slot,.block-caption,.field-label,.branch-tools,.letter_cover,.letter-hint,.receipt-title,.barcode,.receipt-foot,.tear-ticket>summary,.ticket-stub,.option-btn,.step-hint').forEach(x=>x.remove());d.querySelectorAll('br').forEach(x=>x.replaceWith('\n'));d.querySelectorAll('p,div').forEach(x=>x.append('\n\n'));return d.textContent.trim().replace(/\n\s*\n/g,'\n\n');}
function page(h){return `<div class="step-text"><div class="step-inner"><div class="text-content">${slot(h)}</div></div></div>`;}
function unwrapStories(h){const temp=document.createElement('div');temp.innerHTML=h;for(const game of [...temp.querySelectorAll('.game-container')].reverse()){const body=document.createDocumentFragment();for(const content of game.querySelectorAll('.text-content > [data-editable],.effect-page-content'))for(const node of content.childNodes){if(node.nodeType===1&&node.matches('.story-step,.step-hint,.option-btn'))continue;body.append(node.cloneNode(true));}game.replaceWith(body);}return temp.innerHTML;}
function effectPage(h,next=''){return `<div class="step-text effect-page${/class="[^"]*letter-scene/.test(h)?' letter-page':''}${/class="[^"]*player-scene/.test(h)?' player-page':''}"><div class="step-inner"><div class="effect-page-content">${h}</div>${next?'<details class="story-step"><summary class="effect-advance" aria-label="点击空白处继续阅读"><span aria-hidden="true">&#160;</span></summary>'+next+'</details>':''}</div></div>`;}
function renderLetter(text,sender='',recipient=''){const blocks=text.split(/\n\s*\n/).filter(x=>x.trim());const groups=Array.from({length:6},()=>[]);blocks.forEach((x,i)=>groups[Math.min(5,Math.floor(i*6/Math.max(6,blocks.length)))].push(x));const names=['top','mid','bot'];const sheet=n=>names.map((name,i)=>`<div class="letter_${name}${n?2:''}"><div class="letter_${name}_text${n?2:''}">${slot(paragraphs(groups[i+n*3].join('\n\n')))}</div></div>`).join('');sender=sender.trim();recipient=recipient.trim();return wrap('letter-scene',`<div class="trifold_letter"><details class="letter-switch" open><summary class="letter_cover" aria-label="展开或收起书信"><div class="letter_cover_stamp"></div>${sender?'<div class="letter_cover_text_top">'+esc(sender)+'</div>':''}${recipient?'<div class="letter_cover_text">'+esc(recipient)+'</div>':''}</summary></details>${sheet(0)}<div class="trifold_letter2" tabindex="0" aria-label="第二张信纸">${sheet(1)}</div></div>`);}
function renderReceipt(text){return wrap('printer-wrapper',`<div class="printer-card"><details class="printer-trigger" open><summary aria-label="轻点打印机打印或收回小票"><div class="printer-header" aria-hidden="true"><span class="printer-indicator"></span><span>THERMAL PRINTER</span></div><div class="printer-slot" aria-hidden="true"></div></summary></details><div class="receipt-window"><div class="receipt">${slot(paragraphs(text))}<div class="receipt-barcode-box"><div class="receipt-barcode-lines" aria-label="装饰条码"></div></div></div></div></div>`);}
function renderTicket(text){return wrap('train-ticket-box',`<div class="ticket-main-body"><div class="ticket-main-text">${slot(paragraphs(text))}</div></div><details class="ticket-tear-action"><summary aria-label="撕下车票副券"><div class="ticket-stub"><span>TEAR HERE</span></div></summary></details>`);}
function insert(r,html,enableStory=false){checkpoint();const parent=r.commonAncestorContainer.nodeType===1?r.commonAncestorContainer:r.commonAncestorContainer.parentElement;const root=parent.closest('[data-editable]')||editor;const fragment=r.createContextualFragment(html);const isBlock=[...fragment.childNodes].some(n=>n.nodeType===1&&/^(DIV|P|DETAILS)$/.test(n.tagName));r.deleteContents();r.collapse(true);const last=fragment.lastChild;if(isBlock){const tailRange=document.createRange();tailRange.selectNodeContents(root);tailRange.setStart(r.startContainer,r.startOffset);const tail=tailRange.extractContents();root.append(fragment);root.append(tail);root.querySelectorAll('p').forEach(p=>{if(!p.textContent.trim()&&!p.querySelector('[data-widget],br'))p.remove();});}else r.insertNode(fragment);editor.focus();const caret=document.createRange();if(last&&last.isConnected){caret.setStartAfter(last);caret.collapse(true);getSelection().removeAllRanges();getSelection().addRange(caret);}savedRange=null;if(enableStory)$('storyFull').checked=true;setEditable();checkpoint();notice('已添加编辑块。效果在下方示例区查看。');}
document.querySelectorAll('[data-effect]').forEach(b=>b.onclick=()=>{if(graphView)return applyGraphEffect(b.dataset.effect);const r=getRange();if(!r)return;const text=plainHTML(rangeHTML(r)),type=b.dataset.effect;const result=type==='letter'?letter(text):type==='receipt'?receipt(text):type==='ticket'?ticket(text):type==='journal'?journal(text):type==='player'?player(text):branch(text);insert(r,result,type==='branch');if(type==='branch'){notice('分支已添加：编辑选项名称和对应剧情，在示例区体验。');}});
let fontRange=null,activeFontArt=null;
document.addEventListener('selectionchange',()=>{const selection=getSelection();if(!selection.rangeCount||selection.isCollapsed)return;const range=selection.getRangeAt(0);const parent=range.commonAncestorContainer.nodeType===1?range.commonAncestorContainer:range.commonAncestorContainer.parentElement;if(parent.closest('.paper-surface')||editor.contains(parent)){fontRange=range.cloneRange();activeFontArt=parent.closest('.font-art,.inline-spoiler,.inline-red-text');}});
function prepareFontEditing(root){root.querySelectorAll('[data-node-id],[data-next-id]').forEach(el=>{delete el.dataset.nodeId;delete el.dataset.nextId;});root.querySelectorAll('details.stack-spoiler').forEach(el=>el.open=true);root.querySelectorAll('.font-art').forEach(art=>{art.querySelectorAll('.chaos-row').forEach(row=>row.remove());const original=art.querySelector('.font-original');if(original){original.style.display='inline';original.contentEditable='true';}});}
function refreshFontLayers(root){if(!root?.querySelectorAll)return;[...(root.matches?.('.font-art')?[root]:[]),...root.querySelectorAll('.font-art')].forEach(art=>{const original=art.querySelector('.font-original');if(!original)return;const text=plainHTML(original.innerHTML),temp=document.createElement('div');temp.innerHTML=fontMarkup(art.classList.contains('font-dense')?'chaos':'stack',text);art.innerHTML=temp.firstElementChild.innerHTML;});}
function fontMarkup(type,text,click=false){const original=esc(text).replace(/\n/g,'<br>');if(type==='inline')return click?`<details class="inline-spoiler"><summary>${original}</summary></details>`:`<span class="inline-red-text">${original}</span>`;const lines=text.split(/\n+/).filter(line=>line.trim());const rows=lines.map(line=>{const t=esc(line),repeat=esc(Array.from({length:Math.max(1,Math.min(12,Math.ceil(90/Math.max(1,Array.from(line).length))))},()=>line).join(''));return `<div class="chaos-row" aria-hidden="true"><b class="chaos-main">${repeat}</b><b class="chaos-echo">${repeat}</b><dfn class="chaos-small">${t}</dfn>${type==='chaos'?`<dfn class="chaos-cross">${repeat}</dfn>`:''}</div>`;}).join('');const body=`<div class="font-art ${type==='chaos'?'font-dense':'font-shadow'}"><span class="font-original">${original}</span>${rows}</div>`;return click?`<details class="stack-spoiler"><summary aria-label="点击展开字体块">███████</summary>${body}</details>`:body;}


function currentFontArt(){if(fontRange&&!fontRange.collapsed&&fontRange.commonAncestorContainer.isConnected){const parent=fontRange.commonAncestorContainer.nodeType===1?fontRange.commonAncestorContainer:fontRange.commonAncestorContainer.parentElement;return parent.closest('.font-art,.inline-spoiler,.inline-red-text');}return activeFontArt?.isConnected?activeFontArt:null;}
function replaceFontMode(art,click,type=null){if(!art?.isConnected)return false;const surface=art.closest('.paper-surface'),original=art.matches('.inline-red-text')?art:art.matches('.inline-spoiler')?art.querySelector('summary'):art.querySelector('.font-original');if(!original)return false;const host=surface||art.closest('[data-editable]')||editor;let outer=art;const wrapper=art.closest('details.stack-spoiler,details.inline-spoiler');if(wrapper&&host.contains(wrapper))outer=wrapper;while(outer.parentElement?.matches('details.stack-spoiler,details.inline-spoiler')&&host.contains(outer.parentElement))outer=outer.parentElement;checkpoint();const temp=document.createElement('div');temp.innerHTML=fontMarkup(type||(art.matches('.inline-spoiler,.inline-red-text')?'inline':art.classList.contains('font-dense')?'chaos':'stack'),plainHTML(original.innerHTML),click);const replacement=temp.firstElementChild;for(const name of ['nodeId','nextId','boardX','boardY'])if(outer.dataset[name]!==undefined)replacement.dataset[name]=outer.dataset[name];outer.replaceWith(replacement);activeFontArt=replacement.matches('.font-art,.inline-spoiler,.inline-red-text')?replacement:replacement.querySelector('.font-art,.inline-spoiler,.inline-red-text');if(surface){prepareFontEditing(surface);surface.dispatchEvent(new Event('input',{bubbles:true}));}else{refreshFontLayers(editor);setEditable();}fontRange=null;getSelection().removeAllRanges();checkpoint();notice(click?'此文字效果已改为点击展开。':'此文字效果已改为直接显示，不再需要点击。');return true;}
document.addEventListener('pointerdown',event=>{const surface=event.target.closest('.paper-surface');if(surface||editor.contains(event.target)){activeFontArt=event.target.closest('.font-art,.inline-spoiler,.inline-red-text');if(activeFontArt)$('fontClick').checked=!!activeFontArt.closest('details.stack-spoiler,details.inline-spoiler');}});
$('fontClick').addEventListener('change',()=>{const art=currentFontArt();if(art)replaceFontMode(art,$('fontClick').checked);});
$('applyFont').addEventListener('mousedown',e=>e.preventDefault());
function applyFontSelection(type){if(!fontRange||fontRange.collapsed||!fontRange.commonAncestorContainer.isConnected)return notice('请先在纸面或正文编辑区选中文字。');const existing=currentFontArt();if(existing)return replaceFontMode(existing,$('fontClick').checked,type);const range=fontRange.cloneRange(),parent=range.commonAncestorContainer.nodeType===1?range.commonAncestorContainer:range.commonAncestorContainer.parentElement,surface=parent.closest('.paper-surface'),field=parent.closest('[data-editable]');if(!surface&&!editor.contains(parent))return notice('请重新选中文字。');if(surface?.closest('.graph-card.choice'))return notice('选项名称是导航标签；请在选项下方的剧情正文中使用字体效果。');const selectionHost=surface||field||editor;if(!selectionHost.contains(range.startContainer)||!selectionHost.contains(range.endContainer))return notice('请在同一块纸面内选择文字。');checkpoint();const text=range.toString();range.deleteContents();const fragment=range.createContextualFragment(fontMarkup(type,text,$('fontClick').checked));const insertedArt=fragment.querySelector('.font-art,.inline-spoiler,.inline-red-text');range.insertNode(fragment);activeFontArt=insertedArt;if(surface){prepareFontEditing(surface);surface.dispatchEvent(new Event('input',{bubbles:true}));}else{refreshFontLayers(editor);setEditable();}checkpoint();fontRange=null;getSelection().removeAllRanges();notice('字体效果已应用；在示例区查看实际效果。');}
$('applyFont').onclick=()=>applyFontSelection('chaos');
$('applyInline').addEventListener('mousedown',e=>e.preventDefault());
$('applyInline').onclick=()=>applyFontSelection('inline');
$('undo').onclick=()=>{clearTimeout(timer);checkpoint();if(cursor>0){cursor--;restore();notice('已撤销。');}};
$('redo').onclick=()=>{if(cursor<history.length-1){cursor++;restore();notice('已重做。');}};
editor.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$(e.shiftKey?'redo':'undo').click();}});
editor.addEventListener('input',()=>{refreshFontLayers(editor);savedRange=null;clearTimeout(timer);timer=setTimeout(checkpoint,350);if(persist())notice('正文已自动保存。');else notice('自动保存失败，请点击「保存到本地」保留正文。');});
editor.addEventListener('paste',e=>{e.preventDefault();const s=getSelection();if(!s.rangeCount||!editor.contains(s.getRangeAt(0).commonAncestorContainer))return;const range=s.getRangeAt(0),host=range.startContainer.nodeType===1?range.startContainer:range.startContainer.parentElement,field=host.closest('[data-field]');const text=e.clipboardData.getData('text/plain');if(field&&['sender','recipient','option-title','audio-url','track-title','track-artist','cover-url'].includes(field.dataset.field)){checkpoint();range.deleteContents();const node=document.createTextNode(text.replace(/\s*\n+\s*/g,' '));range.insertNode(node);range.setStartAfter(node);range.collapse(true);s.removeAllRanges();s.addRange(range);savedRange=null;checkpoint();}else insert(range,paragraphs(text));});
editor.addEventListener('click',e=>{const button=e.target.closest('button[data-action]');if(!button)return;e.preventDefault();checkpoint();const block=button.closest('.edit-block');if(button.dataset.action==='remove-block'){block.replaceWith(document.createRange().createContextualFragment(paragraphs(editorText(block))));}else if(button.dataset.action==='add-option'){const options=block.querySelector('[data-field=options]');options.insertAdjacentHTML('beforeend',optionEditor(nextOptionTitle(options),''));}else if(button.dataset.action==='remove-option'){const option=button.closest('.branch-option');if(option.parentElement.children.length<=2)return notice('分支至少保留两个选项。');option.remove();}else if(button.dataset.action==='toggle-ending'){const option=button.closest('.branch-option');setOptionEnding(option,option.dataset.ending!=='true');}savedRange=null;setEditable();checkpoint();});
function showView(kind){activeFontArt=null;fontRange=null;checkpoint();originalView=kind==='original';graphView=kind!=='original'&&kind!=='detail';document.querySelector('.workspace').classList.toggle('graph-mode',graphView);document.querySelector('main').classList.toggle('graph-layout',graphView);$('editingPaper').hidden=graphView;$('graphArea').hidden=!graphView;document.querySelector('.canvas-controls').hidden=!graphView;editor.hidden=false;$('rawDocument').hidden=true;setEditable();savedRange=null;$('editView').setAttribute('aria-pressed',String(!originalView));$('original').setAttribute('aria-pressed',String(originalView));if(graphView)renderGraph();notice(graphView?'工作台：直接编辑节点，分支沿连线展开；工具在右侧。':originalView?'原文可直接输入和粘贴；信件、分页和分支保留在各自编辑块中，修改同步到工作台。':'编辑区只编辑内容；在下方示例区查看效果。');}
$('original').onclick=()=>showView('original');$('editView').onclick=()=>showView('edit');
$('mode').onclick=()=>{renderPreview();$('previewPanel').scrollIntoView({behavior:'smooth',block:'start'});};$('replay').onclick=renderPreview;
function clean(){return renderHTML();}
function showCode(kind){const cssVisible=kind==='css'&&!$('noCSS').checked;$('htmlPanel').hidden=cssVisible;$('cssPanel').hidden=!cssVisible;$('htmlTab').setAttribute('aria-pressed',String(!cssVisible));$('cssTab').setAttribute('aria-pressed',String(cssVisible));$('copyCode').dataset.copy=cssVisible?'cssOutput':'htmlOutput';}
function generate(){checkpoint();try{$('htmlOutput').value=clean();}catch(error){$('htmlOutput').value='';notice('无法生成：'+error.message);return false;}$('cssOutput').value=$('noCSS').checked?'':css;$('outputPanel').hidden=false;$('cssTab').hidden=$('noCSS').checked;showCode('html');notice('代码已生成。');}
$('generate').onclick=generate;$('noCSS').onchange=()=>{if(!$('outputPanel').hidden)generate();};$('htmlTab').onclick=()=>showCode('html');$('cssTab').onclick=()=>showCode('css');
function download(name,content,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),60000);}
document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const t=$(b.dataset.copy);if(!t.value)return notice('请先生成代码，复制 CSS 前取消勾选「不要 CSS」。');try{await navigator.clipboard.writeText(t.value);notice('已复制。');}catch{t.focus();t.select();notice('请使用系统复制操作复制选中的代码。');}});
function saveLocalDocument(){showFilePanel(true);persist();const stamp=new Date().toISOString().replace(/[:.]/g,'-');download('纸间-正文-'+stamp+'.json',JSON.stringify(documentRecord(),null,2),'application/json');notice('已请求下载；若没有弹出保存，请在草稿面板复制完整内容。');}
function showFilePanel(saving){$('filePanel').hidden=false;$('filePanelTitle').textContent=saving?'保存草稿':'打开草稿';$('portableText').value=saving?JSON.stringify(documentRecord(),null,2):'';$('filePanelStatus').textContent='';$('filePanel').scrollIntoView({block:'center',behavior:'smooth'});}
$('closeFilePanel').onclick=()=>$('filePanel').hidden=true;
$('portableFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{$('portableText').value=await file.text();$('filePanelStatus').textContent='文件已读取，点击「导入草稿」。';}catch{$('filePanelStatus').textContent='无法读取文件，请粘贴 JSON 文件内容。';}};
$('importPortable').onclick=()=>{try{loadDocument(parseDocument($('portableText').value));$('filePanel').hidden=true;}catch{$('filePanelStatus').textContent='无法导入：请使用完整的纸间 JSON 草稿文件内容。';}};
$('copyPortable').onclick=async()=>{const area=$('portableText');try{await navigator.clipboard.writeText(area.value);$('filePanelStatus').textContent='草稿已复制，请粘贴到本地文本文件中保存。';}catch{area.focus();area.select();area.setSelectionRange(0,area.value.length);$('filePanelStatus').textContent='请长按选中文字，使用系统复制，再保存到本地文本文件。';}};
$('downloadPortable').onclick=()=>download('纸间-草稿.json',$('portableText').value,'application/json');
$('saveDocument').onclick=saveLocalDocument;
$('openDocument').onclick=()=>showFilePanel(false);
$('documentFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{const record=parseDocument(await file.text());loadDocument(record);}catch{notice('无法打开：请选择纸间「保存到本地」生成的 JSON 正文文件。');}};
$('restoreBackup').onclick=()=>{const record=readStored(BACKUP_KEY);if(!record)return notice('当前浏览器没有可恢复的备份。');loadDocument(record);};
for(const id of ['storyFull','noCSS','storyTheme'])$(id).addEventListener('change',()=>{checkpoint();persist();});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&!e.altKey&&e.key.toLowerCase()==='s'){e.preventDefault();saveLocalDocument();}});
window.addEventListener('pagehide',persist);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')persist();});
$('downloadHTML').onclick=exportMinitoolZIP;

function editBody(h,field='body'){return `<div class="edit-body" data-field="${field}" data-placeholder="${field==='option-body'?'填写这条分支的剧情…':'输入正文…'}" data-editable="true" contenteditable="true">${h}</div>`;}
function editField(value,field,label){return `<label class="inline-field"><span class="field-label">${label}</span><span class="edit-field" data-field="${field}" data-placeholder="可留空" data-editable="true" contenteditable="true">${esc(value)}</span></label>`;}
function afterTextField(){return '<div class="after-text-field" data-field="after-text" data-editable="true" contenteditable="true" data-placeholder="在此效果下方继续写正文…"></div>';}
function editBlock(type,label,body){return `<div class="widget edit-block" data-widget="${type}" contenteditable="false"><div class="block-caption"><span>${label}</span><button data-action="remove-block" title="移除效果，保留文字" aria-label="移除${label}效果">×</button></div>${body}${type==='branch'?'':afterTextField()}</div>`;}
function letter(text,sender='',recipient=''){return editBlock('letter','书信',`<div class="letter-fields">${editField(sender,'sender','来信人')}${editField(recipient,'recipient','收信人')}</div>${editBody(paragraphs(text))}`);}
function player(text=''){return editBlock('player','音乐播放器',`<div class="player-fields">${editField('','audio-url','音频直链 HTTPS / 本地音乐')}<button type="button" data-action="choose-music">选择本地背景音乐</button>${editField('','track-title','曲名')}${editField('','track-artist','作者')}${editField('','cover-url','封面链接 HTTPS')}</div>${editBody(paragraphs(text))}`);}
function mediaURL(value){if(value.startsWith('paper-audio:'))return musicAssetSource(value);try{const url=new URL(value);return url.protocol==='https:'?url.href:'';}catch{return '';}}
function renderPlayer(source){const url=mediaURL(fieldText(source,'audio-url')),cover=mediaURL(fieldText(source,'cover-url')),title=fieldText(source,'track-title'),artist=fieldText(source,'track-artist');return `<div class="player-scene">${partsHTML(renderParts(source.querySelector('[data-field=body]')))}<div class="ipod-nano-card record-player"><div class="record-deck" aria-hidden="true"><div class="record-vinyl"><div class="record-label">${cover?`<img class="record-artwork" src="${esc(cover)}" alt="">`:''}</div></div><div class="record-arm"><span></span></div></div><div class="record-meta"><div class="ipod-nano-title">${esc(title)}</div><div class="ipod-nano-artist">${esc(artist)}</div></div>${url?`<audio class="ipod-nano-audio" controls loop preload="none" src="${esc(url)}" aria-label="${esc(title||'音乐播放器')}"></audio>`:'<span class="ipod-audio-empty">请设置音乐链接或选择本地音乐</span>'}</div></div>`;}
